import 'package:flutter/material.dart';import '../services/cart_service.dart';import '../models/cart_item.dart';import '../services/session_service.dart';import '../screens/profile_page.dart';import '../screens/login_page.dart';import '../screens/checkout_page.dart';import '../services/auth_service.dart';class BasketPage extends StatelessWidget{  static const routeName='/basket';  @override  Widget build(BuildContext context){    return Scaffold(      backgroundColor: const Color(0xFFF6F7FB),      appBar: AppBar(        title: const Text('Basket'),        backgroundColor: Colors.white,        foregroundColor: Colors.black,        elevation: 0,      ),      body: ValueListenableBuilder<List<CartItem>>(        valueListenable: CartService.instance.cart,        builder: (context,items, _){          if (items.isEmpty){            return const Center(              child: Text('Your basket is empty',style: TextStyle(fontSize: 16),),            );          }          return Column(            children: [              Expanded(child: ListView.builder(                padding: const EdgeInsets.all(16),                itemCount: items.length,                itemBuilder: (context,index){                  final item=items[index];                  return Container(                    margin: const EdgeInsets.only(bottom: 12),                    padding: const EdgeInsets.all(12),                    decoration: BoxDecoration(                      color: Colors.white,                      borderRadius: BorderRadius.circular(16),                      boxShadow: [                        BoxShadow(                          color: Colors.black.withOpacity(0.05),                          blurRadius: 10,                        ),                      ],                    ),                    child: Row(                      children: [                        Image.network(                          "${AuthService.baseUrl}${item.image}",                          height: 60,                          width: 60,                        ),                        const SizedBox(width: 12),                        Expanded(child: Column(                          crossAxisAlignment: CrossAxisAlignment.start,                          children: [                            Text(item.name,style: const TextStyle(fontWeight: FontWeight.bold)),                            Text('\$${item.price}'),                          ],                        ),                        ),                        IconButton(icon: const Icon(Icons.remove), onPressed: (){                          CartService.instance.decrease(item);                        },                        ),                        Text('${item.quantity}'),                        IconButton(onPressed: (){                          CartService.instance.increase(item);                        }, icon: const Icon(Icons.add)                        ),                        IconButton(onPressed: (){                          CartService.instance.removeItem(item);                        }, icon:const Icon (Icons.delete)                         ),                      ],                    ),                  );                },              ),              ),              Container(                padding: const EdgeInsets.all(16),                decoration: const BoxDecoration(                  color: Colors.white,                  borderRadius: BorderRadius.only(                    topLeft: Radius.circular(18),                    topRight: Radius.circular(18),                  ),                ),                child: Column(                  mainAxisSize: MainAxisSize.min,                  children: [                    Row(                      mainAxisAlignment: MainAxisAlignment.spaceBetween,                      children: [                        const Text('Total',style: TextStyle(fontSize: 16,fontWeight: FontWeight.bold),                        ),                        Text('\$${CartService.instance.totalPrice.toStringAsFixed(0)}',style: const TextStyle(fontSize: 16,fontWeight: FontWeight.bold),),                                            ],                    ),                    const SizedBox(height: 14),                    SizedBox(                      width: double.infinity,                      height: 44,                      child: ElevatedButton(                        onPressed: (){                          final user=SessionService.currentUser.value;                          if (user==null){                            ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("please login to continue")),);                            Navigator.pushNamed(context, LoginPage.routeName);                            return;                          }                          final address=(user.address??'').trim();                          if(address.isEmpty){                            showDialog(context:context,builder:(_){                                return AlertDialog(                                  backgroundColor:Colors.white,                                  shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20),),                                  titlePadding:const EdgeInsets.fromLTRB(24,24,24,8),                                  contentPadding:const EdgeInsets.fromLTRB(24,0,24,16),                                  actionsPadding:EdgeInsets.fromLTRB(16,0,16,16),                                  title:Row(                                    children:[                                      Container(                                        decoration:BoxDecoration(borderRadius:BorderRadius.circular(12),),                                        child:const Icon(Icons.location_on_outlined,color:Colors.black87,size:22,),                                      ),                                      const SizedBox(width:12),                                      const Expanded(                                        child:Text("Address required",style:TextStyle(fontSize:18,fontWeight:FontWeight.w700,color:Colors.black,),),                                      ),                                    ],                                  ),                                  content:const Text("Please add your address before continuing to checkout",style:TextStyle(fontSize:14,color:Colors.black87,height:1.4,),),                                  actions:[                                    TextButton(                                      onPressed:(){                                        Navigator.pop(context);                                      },                                      style:TextButton.styleFrom(                                        foregroundColor:Colors.black54,                                        padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),                                      ),                                      child: const Text("Cancel",style:TextStyle(fontWeight: FontWeight.w500),),                                    ),                                    ElevatedButton(                                      onPressed:(){                                        Navigator.pop(context);                                        Navigator.pushNamed(context,ProfilePage.routeName,arguments:{"id":user.id,"username":user.username,"email":user.email,},);                                      },                                      style:ElevatedButton.styleFrom(                                        backgroundColor:Colors.black,                                        foregroundColor:Colors.white,                                        elevation:0,                                        padding:const EdgeInsets.symmetric(horizontal:16,vertical:10),                                        shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(12),),                                      ),                                      child:const Text("Go to profile",style:TextStyle(fontWeight:FontWeight.w600),                                      ),                                    ),                                  ],                                );                              },                            );                            return;                          }                          Navigator.pushNamed(context, CheckoutPage.routeName);                        },                        style: ElevatedButton.styleFrom(                          backgroundColor: const Color(0xFF111827),                          foregroundColor: Colors.white,                          elevation: 0,                          shape: RoundedRectangleBorder(                            borderRadius: BorderRadius.circular(14),                          ),                        ),                        child: const Text(                          'Checkout',style: TextStyle(fontSize: 15,fontWeight: FontWeight.w600),                        ),                      ),                    )                  ],                ),                )            ],          );        }      ),    );  }}